#!/usr/bin/env python3
import argparse,hashlib,json,plistlib,re,subprocess
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=True);root=Path(__file__).resolve().parent
sdk=subprocess.check_output(['xcrun','--sdk','iphoneos','--show-sdk-path'],text=True).strip();cc=subprocess.check_output(['xcrun','--sdk','iphoneos','--find','clang'],text=True).strip();flags=['-target','arm64-apple-ios17.0','-march=armv8-a','-isysroot',sdk,'-O2','-std=c11','-fblocks','-Wall','-Wextra','-Werror','-framework','CoreFoundation','-lobjc','-lz']
ent=a.output/'entitlements.plist';ent.write_bytes(plistlib.dumps({'platform-application':True,'get-task-allow':True,'task_for_pid-allow':True,'com.apple.system-task-ports':True,'com.apple.private.cs.debugger':True,'com.apple.private.security.no-container':True,'com.apple.private.thread-set-state':True,'com.apple.private.xpc.service-attach':True,'com.apple.hid.system.user-access-service':True,'com.apple.private.hid.client.event-monitor':True,'com.apple.private.hid.client.event-dispatch':True,'com.apple.private.hid.manager.client':True}));files={}
for name,extra in [('display-control',[]),('LiveDisplay.dylib',['-dynamiclib','-DZETA_DISPLAY_DYLIB=1'])]:
 out=a.output/name;subprocess.run([cc,*flags,*extra,str(root/'display-control.c'),'-o',str(out)],check=True);subprocess.run(['codesign','-f','-s','-','--pagesize','4096','--identifier','org.unixnu.zeta.'+name,'--entitlements',str(ent),str(out)],check=True);detail=subprocess.run(['codesign','-d','--verbose=4',str(out)],capture_output=True,text=True,check=True).stderr;h=re.search(r'^CDHash=([0-9a-f]{40})$',detail,re.M);assert h;files[name]={'sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'cdhash':h[1],'bytes':out.stat().st_size};(a.output/(name+'.codesign.txt')).write_text(detail)
(a.output/'trust.json').write_text(json.dumps({'files':files,'native_execution_pending':True},indent=2)+'\n')
